    "questionType": "discurso referido",
    "diff": "media",
    "q": "Leo asked his friend, “Can I borrow your dictionary?” Which sentence correctly reports his question?",
    "o": [
      "Leo asked his friend that he could borrow his dictionary.",
      "Leo asked his friend if could he borrow his dictionary.",
      "Leo asked his friend if he can borrowed his dictionary.",
      "Leo asked his friend if he could borrow his dictionary."
    ],
    "a": 3,
    "explanations": [
      "That no introduce aquí la pregunta indirecta de sí/no. Se necesita if o whether para conservar el sentido de preguntar.",
      "Después de if se usa orden declarativo: he could borrow. La inversión could he corresponde a una pregunta directa, no a esta subordinada.",
      "Después de un modal se usa el verbo base borrow, nunca borrowed. En este reporte en pasado también corresponde el ajuste can → could.",
      "Una pregunta indirecta de sí/no usa if o whether y orden sujeto + verbo: he could borrow. Can pasa a could en este reporte en pasado; no se conserva la inversión de la pregunta directa."
    ],
